1. //! GitHub release client for derrick upgrades.
2. 
3. use serde::{Deserialize, Deserializer};
4. use thiserror::Error;
5. 
6. const GITHUB_API: &str = "https://api.github.com";
7. const REPO: &str = "lgulliver/derrick";
8. 
9. /// A downloadable asset attached to a GitHub release.
10. #[derive(Clone, Debug, Deserialize, Eq, PartialEq)]
11. pub struct ReleaseAsset {
12.     pub(crate) name: String,
13.     #[serde(rename = "browser_download_url")]
14.     pub(crate) browser_download_url: String,
15. }
16. 
17. impl ReleaseAsset {
18.     /// Returns the release asset name.
19.     pub fn name(&self) -> &str {
20.         &self.name
21.     }
22. }
23. 
24. /// A GitHub release returned by the releases API.
25. #[derive(Clone, Debug, Deserialize, Eq, PartialEq)]
26. pub struct GithubRelease {
27.     #[serde(rename = "tag_name", deserialize_with = "deserialize_semver_tag_name")]
28.     pub(crate) tag_name: String,
29.     pub(crate) assets: Vec<ReleaseAsset>,
30. }
31. 
32. impl GithubRelease {
33.     /// Returns the release tag name normalized as semver.
34.     pub fn tag_name(&self) -> &str {
35.         &self.tag_name
36.     }
37. 
38.     /// Returns the assets attached to this release.
39.     pub fn assets(&self) -> &[ReleaseAsset] {
40.         &self.assets
41.     }
42. }
43. 
44. /// Errors returned by the GitHub release client.
45. #[derive(Debug, Error)]
46. pub enum ReleaseClientError {
47.     /// Building the HTTP client failed.
48.     #[error("failed to build GitHub release HTTP client: {0}")]
49.     BuildClient(#[source] reqwest::Error),
50.     /// A request to GitHub or response decode failed.
51.     #[error("GitHub release request failed: {0}")]
52.     Request(#[from] reqwest::Error),
53.     /// GitHub returned no releases for Derrick.
54.     #[error("GitHub returned no releases for lgulliver/derrick")]
55.     NoRelease,
56. }
57. 
58. #[async_trait::async_trait]
59. pub(crate) trait ReleaseClient: Send + Sync {
60.     async fn latest_release(&self) -> Result<GithubRelease, ReleaseClientError>;
61. 
62.     async fn download_asset(&self, asset: &ReleaseAsset) -> Result<Vec<u8>, ReleaseClientError>;
63. }
64. 
65. #[derive(Clone, Debug)]
66. /// Reqwest-backed GitHub release client.
67. pub struct ReqwestReleaseClient {
68.     client: reqwest::Client,
69. }
70. 
71. impl ReqwestReleaseClient {
72.     /// Creates a release client using Derrick's GitHub releases endpoint.
73.     pub fn new() -> Result<Self, ReleaseClientError> {
74.         let client = reqwest::Client::builder()
75.             .user_agent(user_agent())
76.             .build()
77.             .map_err(ReleaseClientError::BuildClient)?;
78.         Ok(Self { client })
79.     }
