     /// Returns the release tag name normalized as semver.
     pub fn tag_name(&self) -> &str {
         &self.tag_name
     }

     /// Returns the assets attached to this release.
     pub fn assets(&self) -> &[ReleaseAsset] {
         &self.assets
     }
