 pub enum ReleaseClientError {
     /// Building the HTTP client failed.
     #[error("failed to build GitHub release HTTP client: {0}")]
     BuildClient(#[source] reqwest::Error),
     /// A request to GitHub or response decode failed.
     #[error("GitHub release request failed: {0}")]
     Request(#[from] reqwest::Error),
     /// GitHub returned no releases for Derrick.
     #[error("GitHub returned no releases for lgulliver/derrick")]
     NoRelease,
 }

