 /// Reqwest-backed GitHub release client.
 pub struct ReqwestReleaseClient {
     client: reqwest::Client,
 }

 impl ReqwestReleaseClient {
     /// Creates a release client using Derrick's GitHub releases endpoint.
     pub fn new() -> Result<Self, ReleaseClientError> {
         let client = reqwest::Client::builder()
             .user_agent(user_agent())
             .build()
             .map_err(ReleaseClientError::BuildClient)?;
         Ok(Self { client })
     }

