     async fn latest_release(&self) -> Result<GithubRelease, ReleaseClientError> {
         let mut releases: Vec<GithubRelease> = self
             .client
             .get(latest_release_url())
             .send()
             .await?
             .error_for_status()?
             .json()
             .await?;
         releases.pop().ok_or(ReleaseClientError::NoRelease)
     }

